insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('fiscal', 'advanced', 'module', 'm01-six-regimes-at-once', 1, 'One call to runFiscalComparison returns four objects. Which one holds the table a reader looks at first, and what decides how many rows it has?', '["summary, one row per regime, so the list of regimes passed in is the only thing that grows it.", "annualCashFlows, whose row count is the fixed 25 year life.", "sensitivityData, because the nine swept prices and the seven swept capex multipliers are what the table reports at each rank.", "insights, which formats one of its five verdicts into each row."]'::jsonb, 0, 'One project goes in and each regime comes back with a complete life of its own, and every ledger inside annualCashFlows is 25 rows long whatever the regime.'),
  ('fiscal', 'advanced', 'module', 'm01-six-regimes-at-once', 2, 'All six templates on the default project return gross revenue of 2686.9277 million USD. What does that identical figure say about a fiscal regime?', '["The six templates happen to share a royalty base, and a template built on a different base would return a different revenue.", "Cost recovery is struck before revenue is reported, so the revenue line is already net of the recoverable pool and equal by construction.", "It touches neither production nor price, so revenue belongs to the field and only the division of it moves.", "Revenue is the figure discounted at 10 percent, which removes the regime''s effect on timing."]'::jsonb, 2, 'On that same 2686.9277 million USD, lifetime contractor net cash flow is 406.2057 million USD under Nigeria - PIA (2021) and 986.7327 under Generic Royalty/Tax.'),
  ('fiscal', 'advanced', 'module', 'm01-six-regimes-at-once', 3, 'The summary comes back sorted. What can be read off a row''s position, and what tie break applies when two regimes match?', '["Contractor NPV descending, with the payback year as the secondary key wherever two NPVs are equal.", "Contractor NPV descending and nothing else, and there is no secondary key at all, so equal NPVs keep the order they were passed in.", "Contractor NPV descending and government take ascending together, since the two mirror each other.", "The internal rate of return descending, so rank 2 at 40.2125 percent above rank 3 at 43.0919 is an error."]'::jsonb, 1, 'summary[0] is the best regime for the contractor and nothing else can be read off a position, and the comparison exposes no option to sort on another column.'),
  ('fiscal', 'advanced', 'module', 'm01-six-regimes-at-once', 4, 'On the default project rank 2 returns an internal rate of return of 40.2125 percent and rank 3 returns 43.0919 percent. What has gone wrong?', '["The two rates were solved at different discount rates, because the bisection reruns each regime against its own hurdle.", "The rank 2 regime failed to converge, so the solver reported the edge of its own bracket in that row instead of a root.", "The rows were ordered on the payback year, which puts a regime with a later payout above one with a higher rate.", "Nothing at all."]'::jsonb, 3, 'Generic Royalty/Tax leads on NPV at 397.0445 million USD with a rate of 44.6574 percent, and Brazil - Concession sits at rank 3 with 357.8728 and 43.0919, so the higher rate and the higher NPV belong to different regimes.'),
  ('fiscal', 'advanced', 'module', 'm01-six-regimes-at-once', 5, 'On ODIDI, Ghana - Deepwater sits at rank 3 collecting 308.8447 million USD for the government and USA - Gulf of Mexico at rank 4 collecting 277.6679. Why does the lower ranked regime collect less?', '["The take column is reported after royalty on that field, and USA - Gulf of Mexico charges the higher flat royalty of the two.", "The sort key is NPV discounted at 12 percent while take is an undiscounted lifetime total, and the larger contractor sum arrives later.", "The ranking was set by the effective tax rate column, where 32.8219 percent sits below 36.5071 percent.", "USA - Gulf of Mexico never pays back on ODIDI, so its take was truncated at the fixed 25 year horizon."]'::jsonb, 1, 'USA - Gulf of Mexico keeps 148.3166 million USD of lifetime contractor net cash flow against 117.1399 for Ghana - Deepwater and ranks lower anyway, paying back in year 7 against year 6.'),
  ('fiscal', 'advanced', 'module', 'm01-six-regimes-at-once', 6, 'Which regime is best for the government on ODIDI, and where is that read from?', '["The regime at rank 2, Generic Royalty/Tax, since the second row is the state''s preference once the contractor''s own pick is set aside.", "Brazil - Concession at rank 1, because on a field where every NPV is negative the leading row is the one the state has squeezed hardest.", "Angola - Deepwater PSC, read out of the take column at 316.7898 million USD, from rank 6.", "Nigeria - PIA (2021), whose 36.9937 percent is the harshest rate of the six."]'::jsonb, 2, 'Nothing in the summary sorts by take, and quoting the second row as the government''s preference is the exact claim the Insights tab used to make.'),
  ('fiscal', 'advanced', 'module', 'm01-six-regimes-at-once', 7, 'The summary''s effective tax rate column divides which two quantities?', '["Government take over government take plus contractor take, with total capex added back into the contractor''s side.", "Government take over government take plus contractor net cash flow, with no adjustment made to either quantity.", "Total tax over total profit oil, which is why a template carrying no resource rent tax reads the lower number.", "Government take over gross revenue, which is why every template on one project shares a denominator."]'::jsonb, 0, 'Total capex on the default project is 500.0000 million USD and the same add-back goes into every row, which turns the ratio into a rate on profit rather than a rate on cash.'),
  ('fiscal', 'advanced', 'module', 'm01-six-regimes-at-once', 8, 'Angola - Deepwater PSC pays 181.7318 million USD of tax on the default project inside a take of 1200.2886, and its effective tax rate column reads 53.4534 percent. What is the column counting?', '["The corporate income tax of 25 percent and the resource rent tax of 50 percent, weighted by the years each of them was actually charged.", "Tax over the contractor''s profit share, which is the statutory rate this template was built to reproduce on a deepwater block.", "The share of gross revenue the state received, which is why it exceeds 25 percent.", "Royalty, the government''s profit oil share and tax together, so most of what it counts is not tax."]'::jsonb, 3, 'USA - Gulf of Mexico is clearer still: its only tax is corporate income tax at 21 percent, its column reads 34.0485 percent, and a flat royalty contributes 503.7989 million USD of the 764.5528 collected.'),
  ('fiscal', 'advanced', 'module', 'm01-six-regimes-at-once', 9, 'On the published comparison built with capex of 20000, Brazil - Concession shows the gentlest effective tax rate in the course, 13.5916 percent, on an NPV of -15354.6816 million USD. Why is it so low?', '["Brazil - Concession charges no royalty on that project, so only its corporate income tax and its resource rent tax reach the numerator.", "The 20000 of capex was added back into the denominator and swamped everything else in it.", "Cost recovery ran at the full limit for all 25 years, so the government''s profit share never began and the tax base stayed at nought.", "The rate is discounted at 10 percent while the take it divides is not."]'::jsonb, 1, 'A rate that falls as the project gets worse is not measuring the harshness of the terms. Angola - Deepwater PSC on the same comparison collects 1662.7835 million USD and reads 32.2800 percent.'),
  ('fiscal', 'advanced', 'module', 'm01-six-regimes-at-once', 10, 'What is the summary''s effective tax rate column not able to be compared with?', '["Another regime in the same table, because the capex added back differs by regime.", "The same regime on a second field, because the add-back is discounted to that field''s own valuation date before the ratio is struck.", "A statutory rate, and the rate the price sensitivity plots, which reads 43.4694 percent where the column reads 33.7901.", "The government take column beside it, which the ratio is built from and therefore ranks in the same order on every project."]'::jsonb, 2, 'Both totals are undiscounted lifetime sums while the NPV beside them is discounted, and the same 500.0000 million USD add-back is applied to every row of one project.'),
  ('fiscal', 'advanced', 'module', 'm01-six-regimes-at-once', 11, 'paybackPeriod and rFactorPayoutYear sit next to each other in the summary. What is the difference between them?', '["Payback is the first year cumulative contractor cash after tax is above zero, and payout is the first year the R factor is above 1.0, a gross test that ignores the government.", "Payback is discounted at the comparison''s rate and payout is not, which is why payout arrives first.", "Payback counts the year capex clears the cost pool, and payout the year the profit oil split first steps down a tranche.", "They test the same event and differ only in rounding, payback down to the whole year and payout up."]'::jsonb, 0, 'USA - Gulf of Mexico on the default project runs cumulative contractor net cash flow of -310.0117, -140.2337 then 8.9905 million USD, and its R factor reads 0.512217, 0.922481 then 1.254640, so both land in year 3.'),
  ('fiscal', 'advanced', 'module', 'm01-six-regimes-at-once', 12, 'On the comparison built with capex of 20000 both year columns come back null for every regime. What does that null mean, and what does it not mean?', '["It means the bisection did not converge, so a longer horizon returns the same nulls.", "It means the government collected nothing on that comparison, which is why the take column reads a flat 0.0000 beside it.", "It means payback falls outside the swept price range and exists at an unswept price.", "It means neither event happened inside the fixed 25 year horizon, and it is neither a zero nor a fast result."]'::jsonb, 3, 'The R factor never passes 1.0 there while the government still collects between 700.1194 and 1662.7835 million USD.'),
  ('fiscal', 'advanced', 'module', 'm01-six-regimes-at-once', 13, 'Both year columns are whole numbers with no interpolation. What does that cost a reader separating two regimes?', '["The columns round to the nearest year, so a regime turning positive halfway through year 4 reports year 4 or year 5 depending on the sign of that year''s cash flow.", "A project that turns positive in the first week of a year and one that turns positive in its last week report the same year.", "Nothing at all, because both are computed on monthly cash flow inside the engine and only reported annually.", "The years are discounted at 10 percent before they are rounded, which compresses a later year against an earlier one."]'::jsonb, 1, 'Neither column is discounted either, while the NPV standing beside them is, so the two year columns and the NPV are not measured on the same money.'),
  ('fiscal', 'advanced', 'module', 'm01-six-regimes-at-once', 14, 'The two Suite test regimes return Flat with an NPV of 1262.3470 million USD, take of 1881.7626 and an effective tax rate of 36.5310, which is exactly the row Generic Royalty/Tax returns on the test project. Why?', '["Both rows were run at the same discount rate of 10 percent, and the effective tax rate is insensitive to everything except the rate.", "The comparison caches one result per project and reuses it whenever the first regime in the list sorts to rank 1 of the summary.", "The four instruments are identical, so a name is not a regime.", "Generic Royalty/Tax is the fallback the engine substitutes for any regime that carries no resource rent tax and no tiered split."]'::jsonb, 2, 'One field and one deck divided by the same royalty, the same cost recovery, the same split and the same tax stack returns the same ledger under either label.'),
  ('fiscal', 'advanced', 'module', 'm01-six-regimes-at-once', 15, 'Which of these does the comparison refuse to do?', '["Accept a discount rate above 10 percent, which is why every published comparison in the course is run at that rate.", "Accept more than six regimes in one call, which is the reason the template set was built with six members in it.", "Vary the 25 year life, though it will accept a capex schedule spread across drilling, facilities and subsea in separate years.", "Schedule capex, which it spends in year 1."]'::jsonb, 3, 'Every dollar of capex lands in year 1, the horizon is fixed at 25 years, and the model carries no abandonment, no depreciation, no loss carryforward and no ring fence.'),
  ('fiscal', 'advanced', 'module', 'm02-the-price-sweep', 1, 'How does the price sweep reach a swept oil price of 40 USD per bbl on the default project?', '["It overwrites the deck with a flat 40 USD per bbl, which removes the step at year 5 and the step at year 10.", "It divides 40 by the first deck point''s oil price of 70 and applies that multiplier to the oil price in every year of the deck.", "It shifts every deck point down by the gap between 40 and 70, keeping the steps but not the ratios between them.", "It rescales the base case NPV by the ratio of the two prices without re-running the ledger."]'::jsonb, 1, 'The multiplier moves the level and leaves the step structure intact, and every one of the nine points is a full re-run of the whole comparison.'),
  ('fiscal', 'advanced', 'module', 'm02-the-price-sweep', 2, 'There is no swept point between 70 and 80 USD per bbl. What is the line the chart draws across that gap?', '["A linear interpolation the engine returns beside the nine points, so any price inside the range can be quoted from it.", "The engine''s answer at the midpoint, because the sweep bisects each interval once to smooth the series it plots.", "The chart''s own line. The engine computed nine points and nothing between them.", "A projection built from the climb, spread evenly across the range."]'::jsonb, 2, 'The nine prices are fixed at 40, 50, 60, 70, 80, 90, 100, 110 and 120 USD per bbl and no input changes them, so a project whose economics turn between two of them cannot be examined there.'),
  ('fiscal', 'advanced', 'module', 'm02-the-price-sweep', 3, 'At 40 USD per bbl the Designer''s default production sharing regime leaves 5.9578 million USD of cost unrecovered at the end of the life. What does that say?', '["The cost recovery limit binds hard at the bottom of the sweep, and the pool closes to 0.7642 at 50 and to 0.0000 from 60 upward.", "The pool carries forward past the horizon, so the contractor recovers the remainder in the following licence period.", "The engine wrote the remainder off as an abandonment provision, which is what makes the NPV smaller than the loss.", "Cost recovery was capped by the profit oil split rather than by the limit, since a low price walks the R factor into a generous tranche."]'::jsonb, 0, 'A limit that never binds at the deck price binds at 40 USD per bbl, where NPV is -51.1673 million USD and the internal rate of return is 6.6994 percent.'),
  ('fiscal', 'advanced', 'module', 'm02-the-price-sweep', 4, 'The nine published price runs are named price_40_pia_default through price_120_pia_default. Which regime do they actually run?', '["The Nigeria - PIA (2021) template, which is why the 70 point returns that template''s NPV of 154.8286 million USD on the default project.", "All six templates at once, with the PIA row published at each price and the other five rows computed and then discarded.", "The Nigeria - PIA (2021) template on the test project, the one project whose first deck point is not 70 USD per bbl.", "The Designer''s own default regime, id 1, Nigerian PIA (PSC)."]'::jsonb, 3, 'The template and the Designer regime share a country and nothing else: cost recovery at 70 percent against 80, and royalty from 12.5 percent against 7.5 percent. The template returns 154.8286 million USD on that project and the Designer regime 173.4150.'),
  ('fiscal', 'advanced', 'module', 'm02-the-price-sweep', 5, 'What does the price sweep return for a regime when total government take plus total contractor net cash flow is not greater than zero?', '["A null, drawn as a break in the series.", "Exactly 0, with no flag, no null and no gap in the line.", "100 percent, on the reasoning that the state took all of a contractor return that was not positive.", "The absolute value of the ratio, which is why a plotted share can run into the thousands."]'::jsonb, 1, 'On the comparison built with capex of 20000 all six templates plot a flat 0.0000 at all nine prices while the government collected between 700.1194 and 1662.7835 million USD.'),
  ('fiscal', 'advanced', 'module', 'm02-the-price-sweep', 6, 'Six series sit flat along zero across the whole sweep on one published comparison. What is the most dangerous way to read them?', '["As a rounding artefact of the one decimal place the sentences print, which a wider number format would resolve.", "As six regimes that collected nothing, which is what a share of 0.0000 percent would mean if the denominator were positive.", "As the most contractor friendly regimes on the chart, when they are the ones whose share could not be computed at all.", "As a comparison run with no regimes loaded, since an empty summary returns an empty list of verdicts."]'::jsonb, 2, 'Angola - Deepwater PSC collected 1662.7835 million USD for the government on that comparison and plots 0.0000 at every one of the nine prices.'),
  ('fiscal', 'advanced', 'module', 'm02-the-price-sweep', 7, 'The Angola template on the default project at three times capex reads 0.0000 at 40 USD per bbl, then 2223.0766, then 144.0692, then 85.6015. How many meanings sit on those four points?', '["Three: the guard firing, the ratio exploding through a near zero denominator, and an ordinary share.", "One, since all four are the same ratio on a curve that is steep.", "Two, a computed share and a missing value, with 2223.0766 and 144.0692 both ordinary shares of a project the state dominates.", "Four, because the engine switches its definition of government take at each swept price as the ledger changes sign."]'::jsonb, 0, 'A share of 0.0000 there means the calculation could not be done, and nothing on the chart separates it from the shares beside it.'),
  ('fiscal', 'advanced', 'module', 'm02-the-price-sweep', 8, 'What must a reader check before quoting any single point off the government share curve?', '["That the point sits at a price the deck itself contains, since only the 70 USD per bbl point is a real deck price.", "That the regime pays back, because the sweep drops any point whose payback year comes back null.", "The discount rate, since the share is computed on discounted totals and moves whenever that rate moves.", "The two lifetime totals underneath it."]'::jsonb, 3, 'If lifetime contractor net cash flow is negative the share is not a share, and if it is negative enough to outweigh the take the curve reads zero and means nothing at all.'),
  ('fiscal', 'advanced', 'module', 'm02-the-price-sweep', 9, 'The sweep reports a climb for each regime. What quantity is that?', '["The average slope against price, fitted across all nine swept points.", "The rise from the curve''s minimum to its maximum, wherever those fall.", "The last swept share minus the first, at full precision, which is two of the nine points.", "The change in share per 10 USD per bbl around the deck price."]'::jsonb, 2, 'On the default project the climbs run from 12.1305 percentage points for Angola - Deepwater PSC down to -17.2498 for USA - Gulf of Mexico.'),
  ('fiscal', 'advanced', 'module', 'm02-the-price-sweep', 10, 'Brazil - Concession climbs 6.0391 percentage points on the default project and is not rising. How are both true?', '["It falls from 50.0329 to 46.6052 over the first three points and only then turns, so the climb is measured from the far side of its own minimum.", "The climb is computed on the test project while the nine plotted points belong to the default project.", "Its resource rent tax at 40 percent is charged only above 90 USD per bbl, so the first three points sit outside the regime.", "The climb includes a capex multiplier of 1.5 that the chart itself does not plot."]'::jsonb, 0, 'An endpoint difference cannot report a shape. Ghana - Deepwater reverses twice inside a positive climb, from 76.7284 down to 76.4647 and from 77.2412 down to 77.0702.'),
  ('fiscal', 'advanced', 'module', 'm02-the-price-sweep', 11, 'Angola - Deepwater PSC climbs 12.1305 percentage points on the default project and -14.8244 on ODIDI with all four of its instruments unchanged. What moved?', '["The discount rate, 10 percent on one field and 12 percent on the other, which reweights the share at every price.", "The field: a different decline, a different deck and a different cost stack change where cost recovery still binds across the range.", "The template, since ODIDI is run against the Designer''s own two regimes rather than against the six templates.", "The swept prices, which are set from each project''s own first deck point and are therefore lower on ODIDI."]'::jsonb, 1, 'The sweep visits the same nine prices on both fields and the shares are undiscounted lifetime totals, so only the project underneath them differs.'),
  ('fiscal', 'advanced', 'module', 'm02-the-price-sweep', 12, 'Which streams does the price multiplier touch?', '["All three, in the ratio the deck''s first year sets, so the mix is preserved while the level moves.", "Oil and NGL, because both are liquids and both are quoted in USD per bbl on the deck.", "All three, but only from the deck''s first step year onward, so the year 1 prices are held where they are.", "Oil alone."]'::jsonb, 3, 'The published case at a price multiplier of 0.5 returns gross revenue of 1419.0195 million USD against the deck''s own 2686.9277, because two of the three streams did not move.'),
  ('fiscal', 'advanced', 'module', 'm02-the-price-sweep', 13, 'A gas weighted project shows a government share that barely moves across the nine points. What is the correct conclusion?', '["The terms are flat rated, so the regime is neither progressive nor regressive.", "The project sits at its cost recovery limit at every price, which pins the share until the recoverable pool clears.", "The sweep did not move most of that project''s revenue, not that its terms are neutral to price.", "The guard failed at every point and returned a constant, as it does whenever contractor net cash flow is negative."]'::jsonb, 2, 'The multiplier scales oil only, so comparing the steepness of two projects'' curves compares their stream mix as much as their terms. The test project is 30000 bbl/d of oil with no gas and no NGL, so there the multiplier is the whole revenue multiplier.'),
  ('fiscal', 'advanced', 'module', 'm02-the-price-sweep', 14, 'On the Designer''s two default regimes at the deck''s own first year price, Concessionary (Royalty/Tax) reads 46.3452 in one place and 59.6210 in another. What separates those two figures?', '["The table adds total capex back into the contractor''s side of the denominator and the chart does not.", "The chart is computed at the swept price and the table at the deck price, which are not the same price.", "The chart counts the government''s profit oil share as well as tax and the table counts tax alone.", "The chart is undiscounted while the table is discounted at 10 percent."]'::jsonb, 0, 'Both are the same ratio on the same cash flows and only the add-back differs. The gap on that row is 13.2758 percentage points, and on Nigerian PIA (PSC) it is 15.9091.'),
  ('fiscal', 'advanced', 'module', 'm02-the-price-sweep', 15, 'Why can a reader not carry one correction between the summary''s effective tax rate and the chart''s?', '["The two are computed on different projects, so a gap measured on one field cannot be carried to another.", "The gap runs from 9.6793 to 17.0850 percentage points across six templates on one project at one price.", "The chart prints four decimal places and the table one, so the offset changes with the rounding.", "The gap changes sign between a regime that adds capex back and one that does not."]'::jsonb, 1, 'The gap grows with the government''s share, so Ghana - Deepwater''s 16.7958 carried across to Generic Royalty/Tax, where it is 9.6793, overstates the chart badly.'),
  ('fiscal', 'advanced', 'module', 'm03-the-capex-sweep', 1, 'What multipliers does the capex sweep hand back with its points?', '["Eight labels, 0.8 through 1.5 inclusive.", "Seven labels from 0.7 to 1.3, the multipliers the published capex cases are run at.", "Seven labels: 0.8, 0.9, 1.0, 1.1, 1.2, 1.3 and 1.4.", "Nine labels, matched to the nine points of the price sweep so that the two charts can be read together."]'::jsonb, 2, 'The loop accumulates 0.1 and arrives at 1.5000000000000004, which fails the test that the multiplier be no greater than 1.5, so it exits one iteration early.'),
  ('fiscal', 'advanced', 'module', 'm03-the-capex-sweep', 2, 'The axis is labelled to a multiplier of 1.5 and the last tick reads 1.4. What ended the loop early?', '["Accumulating 0.1 in binary floating point arrives at 1.5000000000000004, which is greater than 1.5.", "The engine refuses a multiplier above 1.4 because no cost recovery limit can absorb a larger overrun.", "The eighth point returned a negative NPV for one regime, so the sweep dropped it.", "The label comes from the loop bound and the points from a step count."]'::jsonb, 0, 'The point is not unreachable. Calling the engine directly at a multiplier of 1.5 returns an ordinary answer, and Nigeria - PIA (2021) still holds 58.5739 million USD of contractor NPV there against 79.1811 at the last swept point.'),
  ('fiscal', 'advanced', 'module', 'm03-the-capex-sweep', 3, 'For Generic Royalty/Tax the sweep reports a loss of 208.0310 million USD across its points. What does the range the axis advertises actually cost?', '["208.0310 million USD, because the eighth point sits inside the swept range and is merely unlabelled.", "244.0782 million USD, the loss over the eight points from 0.8 to 1.5.", "257.3831 million USD, the NPV the last swept point returns.", "465.4141 million USD, the contractor NPV at the first swept point, since the loss runs from there down to nothing."]'::jsonb, 1, 'The seven swept points understate the loss the axis promises. For USA - Gulf of Mexico the two figures are 228.7953 and 267.7301 million USD.'),
  ('fiscal', 'advanced', 'module', 'm03-the-capex-sweep', 4, 'Does the point the loop never reaches change which regime the resilience verdict names on the default project?', '["Yes. Over eight points Ghana - Deepwater gives up 109.8425 million USD and takes the title from Angola - Deepwater PSC.", "Yes, because the eighth point is where the two regressive templates cross the two whose split is tiered on the R factor.", "It cannot be known, because the engine returns no value at all at a multiplier of 1.5 for any of the six templates.", "No, the winner is the same either way."]'::jsonb, 3, 'Angola - Deepwater PSC gives up the least on seven points at 84.8591 million USD and on eight at 107.3918, and USA - Gulf of Mexico the most in both, so what moves is the quantity attached to the winner.'),
  ('fiscal', 'advanced', 'module', 'm03-the-capex-sweep', 5, 'The capex verdict ranks one quantity per regime. Which quantity?', '["The contractor NPV at the first swept point minus the NPV at the last, in million USD, which prices a 20 percent underspend against a 40 percent overrun.", "The slope of contractor NPV against the multiplier, fitted across all seven of the swept points.", "The fraction of base case NPV that survives a 50 percent overrun, which is why it reads as a percentage.", "The multiplier at which contractor NPV first turns negative, so a higher figure is the more resilient regime."]'::jsonb, 0, 'It is an absolute amount between two endpoints, so it reports neither the shape between them nor a percentage of the base NPV.'),
  ('fiscal', 'advanced', 'module', 'm03-the-capex-sweep', 6, 'USA - Gulf of Mexico is named the least resilient at 228.7953 million USD given up, on a base contractor NPV of 382.0660. Why is that not obviously the worse choice?', '["The sweep holds price at the deck, and USA - Gulf of Mexico is the most progressive of the six on that project.", "The 228.7953 is quoted over seven points while the other five regimes are quoted over eight.", "The loss is an absolute amount, so a regime with more NPV to lose is penalised for having it.", "The base NPV of 382.0660 is discounted at 10 percent while the loss beside it is not discounted at all."]'::jsonb, 2, 'Angola - Deepwater PSC is named the most resilient at 84.8591 million USD given up on a base NPV of 223.7100, so the verdict prefers the smaller prize because it shrinks more slowly.'),
  ('fiscal', 'advanced', 'module', 'm03-the-capex-sweep', 7, 'Angola - Deepwater PSC returns 232.3129 million USD at a multiplier of 0.8 and 238.0330 at 0.9. What makes spending more capital pay?', '["Its cost recovery limit of 50 percent lets a larger pool be recovered faster, so the contractor is repaid sooner.", "Its resource rent tax at 50 percent has a base cut by an annual uplift computed from total capex, so a larger capex enlarges the deduction in every year of the life.", "The larger capex lowers the R factor and holds the contractor in the 70 percent tranche, which outweighs the spend.", "Its royalty of 0 percent leaves capex as the only deduction, so the deduction grows with no royalty offsetting it."]'::jsonb, 1, 'Brazil - Concession, with a resource rent tax at 40 percent, shows the muted version of the same thing, giving up only the step from 369.1782 to 367.7987 over the same interval.'),
  ('fiscal', 'advanced', 'module', 'm03-the-capex-sweep', 8, 'The seven published capex cases are named capex_0.7_pia_default to capex_1.3_pia_default. How do they relate to the sweep the chart draws?', '["They are the seven swept points themselves, published one case per label on the chart''s axis.", "They are the same regime as the chart over a shifted range, the Nigeria - PIA (2021) template under the name the Designer gives it.", "They are the oracle''s eight point sweep with the point at a multiplier of 1.5 taken out of it.", "A different range on a different regime."]'::jsonb, 3, 'The published set runs the Designer''s default regime, id 1, at multipliers of 0.7 to 1.3, returning 173.4150 million USD of NPV at 1.0 where the template returns 154.8286, and the chart sweeps 0.8 to 1.4 on the templates.'),
  ('fiscal', 'advanced', 'module', 'm03-the-capex-sweep', 9, 'Across the published capex cases the payback year steps 3, 3, 4, 4, 4, 5 and 5 while the payout year steps 2, 2, 2, 3, 3, 3 and 4. What does that add to the NPV story?', '["Nothing, since both are integers and an integer cannot resolve a 10 percent step in capex.", "That payback and payout are one test read to two precisions, which is why they step together.", "An overrun also delays the year the contractor turns positive and the year the R factor passes 1.0, and can move a profit split tier with it.", "That the sweep re-runs the discounting alone, the ledger underneath being unchanged by the multiplier."]'::jsonb, 2, 'NPV over the same range runs 240.3937, 218.5119, 198.2887, 173.4150, 150.6191, 123.6342 and 98.2520 million USD, so the curve is not a straight line either.'),
  ('fiscal', 'advanced', 'module', 'm03-the-capex-sweep', 10, 'State the unit and the number of points of each of the two sweeps the comparison returns.', '["A government share in percent at nine oil prices, and contractor NPV in million USD at seven capex multipliers.", "Contractor NPV in million USD at nine oil prices, and a government share in percent at seven capex multipliers, which is the pairing the two axis titles suggest.", "A government share in percent on both, nine points on price and eight on capex.", "Contractor NPV in million USD on both, so the two charts can be subtracted point by point."]'::jsonb, 0, 'Only the capex chart''s values can be added or subtracted as amounts, and only the price chart''s can be compared between projects of different sizes.'),
  ('fiscal', 'advanced', 'module', 'm03-the-capex-sweep', 11, 'On the default project the most progressive template gives up the least contractor NPV and the two regressive ones give up the most. Why is that agreement not a coincidence?', '["The two verdicts are computed by the same reduce over the same array, so they cannot disagree.", "A regime taking a rising share of the upside absorbs a share of the downside too, so the contractor''s NPV moves less when capital cost rises.", "Both sweeps hold the other variable at its base case, which forces the two rankings to match row for row, so a regime placed third by climb is placed third by loss as well.", "The price climb is an input to the capex loss, which is why the two orderings track one another so closely."]'::jsonb, 1, 'Angola - Deepwater PSC climbs 12.1305 percentage points and gives up 84.8591 million USD while USA - Gulf of Mexico climbs -17.2498 and gives up 228.7953, and the orders agree in tendency and not row for row.'),
  ('fiscal', 'advanced', 'module', 'm03-the-capex-sweep', 12, 'On ODIDI, which regime wins both sweep verdicts and which one breaks the pattern?', '["Brazil - Concession wins both, since it leads the summary on that field at -5.8662 million USD.", "Angola - Deepwater PSC wins both, as it does on the default project, and Ghana - Deepwater is the one that breaks the pattern.", "No regime wins both, because every climb on that field is negative and a negative climb cannot win the price verdict.", "Ghana - Deepwater wins both, most progressive at 1.9971 percentage points and most resilient at 150.9021 million USD, and Angola - Deepwater PSC breaks it."]'::jsonb, 3, 'Angola''s climb of -14.8244 is not the worst on that field while its capex loss of 215.1075 million USD is the largest of the six.'),
  ('fiscal', 'advanced', 'module', 'm03-the-capex-sweep', 13, 'Which case does a project team fear that neither sweep contains?', '["An opex overrun, which the capex multiplier does not touch, though the two curves can be combined into it by eye.", "A delay to first production, which both sweeps do cover through the payback year they compute at every point.", "An overrun arriving at a low price.", "A discount rate above the base case, which the price sweep covers implicitly by re-running the whole comparison."]'::jsonb, 2, 'The price sweep holds capex at the base case at every price and the capex sweep holds price at the deck at every multiplier. The Angola template at three times capex reads 0.0000 at 40 USD per bbl and 2223.0766 at 50, and neither sweep as drawn would have suggested it.'),
  ('fiscal', 'advanced', 'module', 'm03-the-capex-sweep', 14, 'On the comparison built with capex of 20000 all six templates give up 10909.090909 million USD across the sweep. What is the verdict that names USA - Gulf of Mexico the most resilient?', '["Not a result. The six losses are identical by construction and differ only in the last bits of a floating point sum.", "A correct ranking on a margin too fine to print, which one more decimal place in the sentence would show.", "A tie broken by the summary''s own sort, which keeps the first row it sees, so the sentence is naming the highest NPV regime under another label.", "A defect in the oracle rather than the engine, since the oracle''s arithmetic names Brazil - Concession."]'::jsonb, 0, 'At a capex of 20000 nothing below the capex line moves between the first swept point and the last, so the whole capex difference reaches the contractor undiluted and is discounted by the same one year in every case. The sentence quotes both regimes at 10909.1 million USD.'),
  ('fiscal', 'advanced', 'module', 'm03-the-capex-sweep', 15, 'Name the three reasons a resilience verdict can differ between two runs.', '["The project life was extended past 25 years, the capex was rescheduled out of year 1, or opex was swept beside capital.", "The field underneath changed, the swept range is not the one the axis claims, or there was nothing to rank.", "The bisection failed to converge, the summary lost its sort, or the golden was re-cut against a new engine.", "One regime paid back and the others did not, one returned a null rate, or one returned an empty list of verdicts."]'::jsonb, 1, 'On ODIDI the same six templates hand the title to Ghana - Deepwater at 150.9021 million USD where Angola - Deepwater PSC held it on the default project at 84.8591.'),
  ('fiscal', 'advanced', 'module', 'm04-the-insights', 1, 'On `cmp_all_templates_default_project` the payback verdict reads that Generic Royalty/Tax pays back in year 3, against year 4 for Angola - Deepwater PSC. Four of the six templates pay back in year 3. Which of the four does the sentence name?', '["Whichever of them crosses zero cumulative contractor net cash flow earliest inside year 3, since the engine interpolates within the year to separate a tie.", "The first of them in summary order, and the summary is sorted by contractor NPV, so the sentence names whichever regime has the highest NPV.", "Angola - Deepwater PSC, because a payback of year 4 is what the comparison clause of the sentence ranks the winner against.", "The one of the four with the smallest government take, 758.7514 million USD, which the tie break reads next."]'::jsonb, 1, 'Payback is an integer year, so a strict less than in a reduce keeps the first element it saw, and that element is the NPV winner at 397.0445 million USD.'),
  ('fiscal', 'advanced', 'module', 'm04-the-insights', 2, 'A payback verdict on ODIDI reads that Brazil - Concession pays back in year 6, against year 8 for Angola - Deepwater PSC. What is the second regime in that sentence?', '["The runner up, the second fastest of the six, which the sentence quotes so a reader can see how tight the top of the column is.", "The regime immediately below the winner in the summary sort, which on ODIDI is Generic Royalty/Tax at year 7.", "The slowest of the rest, because the function takes the fastest, removes it, and then takes the maximum of what is left.", "The median of the payback column, chosen so that one outlier cannot make the spread look wider than it is."]'::jsonb, 2, 'It reads like a top two and is a top and a bottom, with the three ODIDI regimes that pay back in year 7 silently in between.'),
  ('fiscal', 'advanced', 'module', 'm04-the-insights', 3, 'On `cmp_never_recovers` all six templates give up 10909.090909 million USD of contractor NPV across the capex sweep. Why are the six losses identical rather than merely close?', '["At both ends of the sweep every regime recovers cost at its own limit, so nothing below the capex line moves and the whole capex difference reaches the contractor''s year 1 line undiluted, discounted by the same one year.", "The sweep reuses the first regime''s ledger for the other five, because nothing pays back and the comparison stops early.", "Every template applies the same cost recovery limit at that capex, so each one recovers an identical fraction of the overrun.", "The loss is rounded before the verdict ranks it, and the six regimes differ only past the sixth decimal place."]'::jsonb, 0, 'The capex delta passes straight to the contractor''s year 1 line, so the loss is the same discounted amount for all six whatever royalty, profit oil and tax each of them carries.'),
  ('fiscal', 'advanced', 'module', 'm04-the-insights', 4, 'The capex verdict on that same comparison names USA - Gulf of Mexico the most resilient at 10909.1 million USD and Nigeria - PIA (2021) the most exposed at 10909.1 million USD. What has the sentence established?', '["That USA - Gulf of Mexico is the safer regime under an overrun, since the engine names it and the golden pins the sentence it returned.", "That the oracle''s arithmetic settles the pick in favour of Brazil - Concession, which is the correct winner wherever the engine''s reduce disagrees with it.", "That the six regimes are separated somewhere past the printed decimals, so the ranking holds and only the rounding of the sentence conceals it.", "Nothing, because the least and the most print the same quantity."]'::jsonb, 3, 'The tie is exact by construction, the golden pins the ranked quantities rather than a winner, and no tie break rule could be right among six answers that are one answer.'),
  ('fiscal', 'advanced', 'module', 'm04-the-insights', 5, 'The price verdict on `cmp_never_recovers` names Nigeria - PIA (2021) the most progressive, its government share rising 0.0 percentage points across the swept range. What produced that climb?', '["The share guard fired at every price, so all nine points of all six series read exactly 0.0000 and every climb is zero.", "Terms that are genuinely neutral to price at that capex, since the royalty is flat and no profit oil ever arises to be split.", "A real difference of a few hundredths of a percentage point, lost when the sentence rounded the climb to one decimal place.", "The oil multiplier cannot move a project carrying that much capex, so the sweep returned the base case nine times over."]'::jsonb, 0, 'Lifetime contractor net cash flow of -16279.9099 million USD outweighs a government take of 1431.0440, the denominator is not positive, and the division returns 0.'),
  ('fiscal', 'advanced', 'module', 'm04-the-insights', 6, 'The Insights tab once called the second ranked regime the one that maximises government revenue. What does the second row of `cmp_all_templates_default_project` actually collect?', '["1339.2784 million USD, because government take descending is the summary''s secondary sort once contractor NPV has ordered the rows.", "758.7514 million USD, the largest of the six, which is why the old sentence looked right on this project.", "764.5528 million USD, while the largest take on that comparison is 1339.2784 million USD and belongs to the regime in sixth place.", "1200.2886 million USD, for Angola - Deepwater PSC, the regime the take column puts second."]'::jsonb, 2, 'The sort carries no information about take, and on this project the take column runs the other way, from 758.7514 at rank 1 to 1339.2784 at rank 6.'),
  ('fiscal', 'advanced', 'module', 'm04-the-insights', 7, '`insights_single_regime` returns three verdicts rather than five. Which two are missing, and why?', '["The payback and government verdicts, because each of their sentences carries a comparison clause that a second regime is needed to fill.", "The capex and price verdicts, because a ranking of one regime is not a ranking.", "The npv and payback verdicts, since one regime has nothing to be best against while both sweeps still return a series to rank.", "None of them, because all five sentence templates fire and the two sweep verdicts name the only regime as both the most and the least resilient."]'::jsonb, 1, 'Both sweeps still run and still produce a series, and the function declines to name a winner among one.'),
  ('fiscal', 'advanced', 'module', 'm04-the-insights', 8, 'What does `insights_empty` return when the comparison is given no regimes at all?', '["Five verdicts whose regime names render blank, since the sentence templates are built before the summary is read.", "One verdict stating that there was nothing to compare, so a panel always has something to render on the tab.", "The three verdicts that do not need a second regime, each reporting the absence rather than a value.", "An empty list."]'::jsonb, 3, 'An empty result is the honest shape for an empty question, and the panel rendering the list has to handle it.'),
  ('fiscal', 'advanced', 'module', 'm04-the-insights', 9, 'The single regime payback verdict reads that Alpha pays back in year 6, and that no other regime pays back within the project life. What is wrong with the second clause?', '["It is true only because there is no other regime, so it reads as a finding about rejected alternatives when it is a statement about an empty set.", "It is false, because the other regimes were compared and at least one of them did pay back inside the 25 years.", "It reports a null as a sentence, which hides that the payback column for the run was never computed at all.", "It quotes the project life as 25 years when the horizon the comparison used was the last year with positive production."]'::jsonb, 0, 'The heading above it still reads Fastest capital recovery, the same wording it carries when six regimes were ranked.'),
  ('fiscal', 'advanced', 'module', 'm04-the-insights', 10, 'On ODIDI the capex verdict names Ghana - Deepwater as giving up the least contractor NPV and Angola - Deepwater PSC the most. What are the two ranked quantities?', '["84.8591 million USD for Ghana - Deepwater and 228.7953 million USD for Angola - Deepwater PSC, the two losses the same verdict reports on the default project.", "150.9021 million USD for Ghana - Deepwater and 215.1075 million USD for Angola - Deepwater PSC.", "16.4714 and 10.9118 million USD, the NPV each returns at the first swept point.", "-134.4307 million USD and -204.1957 million USD, the contractor NPV each regime returns at the last swept multiplier."]'::jsonb, 1, 'The quantity is the first swept point minus the last: Ghana runs 16.4714 down to -134.4307 and Angola 10.9118 down to -204.1957.'),
  ('fiscal', 'advanced', 'module', 'm04-the-insights', 11, 'On ODIDI the price verdict calls Ghana - Deepwater the most progressive, rising 2.0 percentage points. What does winning on that number say about the field?', '["Ghana - Deepwater is a progressive regime, a property of its four instruments that the sweep has now measured on a second field.", "The climb is small because the sweep scales oil only, and ODIDI carries gas at 40 Mscf/d and NGL at 900 bbl/d that never move.", "Nobody captures upside on ODIDI: the actual climb is 1.9971 and only one other regime climbs at all, Nigeria - PIA (2021) by 0.1968.", "Two percentage points is the smallest climb the verdict will report, below which the sentence is omitted for want of separation."]'::jsonb, 2, 'The other four climbs on ODIDI are negative, as far down as -37.6994 for USA - Gulf of Mexico, so the winner is the least regressive of six.'),
  ('fiscal', 'advanced', 'module', 'm04-the-insights', 12, '`insights_rounding` pins how the verdict sentences print their numbers. What is it guarding?', '["That every money and rate figure inside a sentence renders at one fixed decimal place, so 0.25 prints as 0.3 and 1.05 prints as 1.1.", "That the engine rounds a quantity before ranking it, which is what lets two regimes tie in a verdict at all.", "That JavaScript and Python agree on every half way case, so a golden written in one language can grade the other.", "That a verdict refuses to print a value it cannot render exactly, and omits the sentence instead."]'::jsonb, 0, 'The ranking runs at full precision and only the sentence rounds, which is why two regimes printing the same figure have not been separated by it.'),
  ('fiscal', 'advanced', 'module', 'm04-the-insights', 13, 'On `insights_never_pays_back` every `paybackPeriod` is null. What does the payback verdict do?', '["It reports the first null it meets as a payback year, which a panel then renders as a blank cell beside the NPV column.", "It changes its heading to Capital recovery and states in one sentence that no regime pays back within the project life.", "It falls back on the R factor payout year, which is a gross test of cumulative revenue over cumulative cost and is defined on the very same ledger.", "It is omitted entirely, in the same way the capex and price verdicts are omitted when only one regime is compared."]'::jsonb, 1, 'The other four verdicts still fire: the contractor sentence still names Alpha at 150.0 million USD with an IRR of 22.0 percent.'),
  ('fiscal', 'advanced', 'module', 'm04-the-insights', 14, '`never_recovers_huge_capex` returns total profit oil 0.0000, total tax 0.0000 and total government take 875.1492 million USD. Which instrument produced the take?', '["The government''s share of profit oil, which is charged before the cost recovery limit is applied and therefore survives the overrun.", "Corporate income tax on the profit share, levied on the gross revenue of 7001.1938 million USD rather than on a base that went negative.", "The minimum tax, which the tax stack applies whenever the computed charge on a loss making project would otherwise be zero.", "Royalty, taken off the top."]'::jsonb, 3, 'Profit oil never appears, so the tax stack never charges anything, and every dollar of the 875.1492 is royalty off the top of revenue.'),
  ('fiscal', 'advanced', 'module', 'm04-the-insights', 15, 'On `cmp_never_recovers` the contractor verdict names Brazil - Concession at -15354.7 million USD with an IRR of 0.0 percent, under a heading that reads best for the contractor. Is the sentence wrong?', '["Yes, because a negative NPV cannot be the highest of anything, and a claim that cannot be supported is supposed to be omitted rather than printed.", "Yes, because an IRR of 0.0 percent means the flows never changed sign, so this project broke even rather than lost money.", "No, it is correct and it describes a catastrophe, because the sort ranks six ways of losing money and rank 1 is the least bad.", "No, and the 0.0 percent IRR confirms it: a rate of zero is the floor the bisection reports when a project exactly returns its outlay."]'::jsonb, 2, 'Highest here means least negative, against -15900.1132 million USD for the worst of the six, and the payback column is null for all of them.'),
  ('fiscal', 'advanced', 'module', 'm05-numbers-to-distrust', 1, 'Nigeria - PIA (2021) on the default project reads an effective tax rate of 59.6432 in the summary table and 76.7282 on the price sweep at 70 USD per bbl. What separates the two?', '["The summary is computed on discounted cash flows at 10 percent while the sweep totals the same ledger undiscounted, so the two answer the same question at different dates.", "The sweep re-ran the comparison at a higher oil price than the deck''s own, so 76.7282 belongs to a later point of the nine and not to the base case.", "The summary adds total capex back into the contractor side of the denominator and the sweep does not, on the same cash flows over the same 25 years.", "The summary counts royalty inside government take and the sweep counts only profit oil and tax, which is why the sweep reads the higher of the two."]'::jsonb, 2, 'Both come out of one call to `runFiscalComparison` and both are labelled effective tax rate, and 17.0850 percentage points separate them.'),
  ('fiscal', 'advanced', 'module', 'm05-numbers-to-distrust', 2, 'A reader proposes to translate between the two effective tax rates with a fixed offset, because the chart runs about ten points above the table. Why does that fail?', '["The gap is not fixed: on one comparison at one price it runs from 9.6793 percentage points for Generic Royalty/Tax to 17.0850 for Nigeria - PIA (2021), and it grows with the government''s share.", "The gap changes with the swept price, so an offset taken at 70 USD per bbl is wrong at every other one of the nine points.", "The offset is stable in percentage points and unstable in money, so it can be carried between rates but never between takes.", "The two rates are computed from different ledgers, so no arithmetic relation between them exists to be approximated by an offset."]'::jsonb, 0, 'A capex add-back of a fixed 500.0000 million USD weighs more heavily on a denominator the state has already thinned, so Ghana - Deepwater shows 16.7958 where Generic Royalty/Tax shows 9.6793.'),
  ('fiscal', 'advanced', 'module', 'm05-numbers-to-distrust', 3, 'On `cmp_never_recovers` the price sweep plots 0.0000 percent for every template at all nine prices, while Angola - Deepwater PSC collected 1662.7835 million USD for the government. What does the zero mean?', '["The government took nothing, because a project that never pays back generates no profit oil and therefore no take at all.", "The guard fired: lifetime contractor net cash flow is negative enough that the denominator is not positive, so the division was declined and 0 returned.", "The share was too large to render, so the series was clamped to zero rather than drawn off the top of the axis.", "The sweep could not scale the oil price on a project of that capex, so it returned the untouched deck at every point."]'::jsonb, 1, 'Take of 1662.7835 against contractor net cash flow of -16511.6494 million USD sums to -14848.8659, and a zero that means not computable is drawn in the same colour as a zero that would mean nothing collected.'),
  ('fiscal', 'advanced', 'module', 'm05-numbers-to-distrust', 4, 'The Angola template on the default project at three times capex plots 0.0000, then 2223.0766, then 144.0692, then 85.6015 across the first four swept prices. How many meanings are on that line?', '["One, a government share that is simply very sensitive to price on a project carrying that much capital.", "Two, an unrenderable value at the first point and a share at the other three, since 2223.0766 is a share of a small denominator.", "Two, a share below the axis at the first point and a share above 100 percent at the other three, which is what an overrun does to any curve.", "Three: the guard firing, a ratio exploding through a near zero denominator, and an ordinary share, in that order."]'::jsonb, 3, 'A government share of several hundred percent is arithmetic and not a fiscal term, and nothing on the chart flags any of the four points.'),
  ('fiscal', 'advanced', 'module', 'm05-numbers-to-distrust', 5, 'The capex sweep is written as a loop from a multiplier of 0.8 to 1.5 in steps of 0.1 and returns seven points. What ends the loop early?', '["The engine caps the sweep at seven points to hold the comparison inside its time budget, since each point re-runs every regime.", "The eighth point is skipped because a multiplier of 1.5 makes the contractor NPV negative for several templates and the axis would need rescaling.", "The accumulating multiplier reaches 1.5000000000000004, which fails the test that it be at most 1.5, so the eighth iteration never runs.", "The loop tests the rounded label rather than the accumulator, so a label of 1.5 is never produced."]'::jsonb, 2, 'The engine returns the labels 0.8, 0.9, 1.0, 1.1, 1.2, 1.3 and 1.4, and the axis it is drawn against still promises 1.5.'),
  ('fiscal', 'advanced', 'module', 'm05-numbers-to-distrust', 6, 'For USA - Gulf of Mexico on the default project the resilience verdict quotes a loss of 228.7953 million USD. What would the range the axis advertises have given?', '["189.4674 million USD, the contractor NPV the regime still returns when the engine is called directly at a multiplier of 1.5.", "267.7301 million USD, the loss to the eighth point at a multiplier of 1.5, which the sweep never visits.", "244.0782 million USD, which is the loss the same eight point range gives for Generic Royalty/Tax rather than for this regime.", "228.4023 million USD, the contractor NPV at the last swept point, which the verdict reports as the loss."]'::jsonb, 1, 'Every resilience number on that chart is understated: Angola - Deepwater PSC is quoted at 84.8591 where the labelled range gives 107.3918.'),
  ('fiscal', 'advanced', 'module', 'm05-numbers-to-distrust', 7, 'Is the resilience sentence false when it prices a range the chart labels 0.8 to 1.5?', '["Yes, because it names a winner the eight point range would not have named, and the ranking is what the sentence claims to establish.", "Yes, because the quantity it prints belongs to a range no reader can see and no input can reproduce from the chart.", "No, because the loop does reach 1.5 and only the axis label is short, so the number and the range it describes agree with each other.", "No, it reports the range the sweep produced, a 20 percent underspend to a 40 percent overrun."]'::jsonb, 3, 'It is answering a narrower question than the label asks, which is harder to catch than a wrong number, and on the default project the named winners survive the change of range.'),
  ('fiscal', 'advanced', 'module', 'm05-numbers-to-distrust', 8, 'The seven published capex cases run multipliers of 0.7 to 1.3 and return NPVs from 240.3937 down to 98.2520 million USD. Which regime do they run?', '["The Designer''s own default regime, the one the price cases also use, which is not the Nigeria - PIA (2021) template despite sharing a country with it.", "The Nigeria - PIA (2021) template, which is why the case at a multiplier of 1.0 returns the same NPV as that template''s summary row.", "All six templates at once, with the case reporting the best contractor NPV of the six at each multiplier.", "The Brazil - Concession template, the regime whose resource rent tax makes a capex sweep worth publishing at all."]'::jsonb, 0, 'Two ranges live in one engine and neither is the one on the axis: the sweep visits 0.8 to 1.4 and the published cases 0.7 to 1.3, where payback slips from year 3 to year 5.'),
  ('fiscal', 'advanced', 'module', 'm05-numbers-to-distrust', 9, 'What can a reader change about the capex sweep to see a 50 percent overrun?', '["The multiplier list, which the comparison accepts alongside the project and the regimes.", "The axis maximum, which is the value the loop tests against and therefore also the value it stops at.", "Nothing about the sweep, since the range, the step and the number of points are written into the loop and no input reaches them.", "The capex lines of the project itself, which is the only supported way to move the range and gives the same seven multipliers around a larger base."]'::jsonb, 2, 'The eighth point exists and is perfectly ordinary, 189.4674 million USD for USA - Gulf of Mexico, but reaching it means calling the ledger function directly at that multiplier.'),
  ('fiscal', 'advanced', 'module', 'm05-numbers-to-distrust', 10, '`calculateIRR` reports 102400.0000 percent on flows of -1 in year 1 and 2000 in year 2. What is that number?', '["The root of the flows, which the 80 bisections found to that precision before the tolerance closed.", "The top of its own search, 100 percent doubled ten times, returned because the NPV was still positive there.", "A clamp typed into the solver to stop a runaway Newton iteration from returning an infinite rate.", "The rate at which the NPV of those flows first crosses zero from below, which is why the golden pins it as the expected value."]'::jsonb, 1, 'The NPV at 102400 percent is 0.0009, small, positive and not zero, while the true root is 199900 percent.'),
  ('fiscal', 'advanced', 'module', 'm05-numbers-to-distrust', 11, 'Two solvers in this package report suspiciously round rates, 102400 percent and 1000 percent. What is the tell a reader should carry?', '["Size rather than roundness, since no real project returns a rate in the thousands of percent and any such value is the edge of a search.", "A rate quoted to four decimal places, which is the format the bisection uses and the Newton iteration does not.", "An IRR reported beside a negative NPV, which is the only combination that a bracket return can produce in either engine.", "Roundness rather than size, because both numbers are the edge of a search."]'::jsonb, 3, 'The published `capex_multiplier_0_7` case returns an IRR of 1095.4783 percent on a real ledger and that is a root, while 1000 is a Newton clamp and 102400 is a doubling bound.'),
  ('fiscal', 'advanced', 'module', 'm05-numbers-to-distrust', 12, '`irr_all_positive` and `irr_npv0_negative` both report 0.0000 percent. What separates them?', '["The first has flows that never change sign on a profitable project, with an NPV at 10 percent of 25.6198, and the second loses money at every rate, with an NPV at 10 percent of -16.5289.", "The first is a true root at zero and the second is the early exit, which is why only the second carries a disagreement in the golden.", "The first was stopped by the bracket and the second by the sign test, so one is a bound and the other a refusal.", "Nothing separates them in the return value or in the flows, since both projects break even exactly at a rate of zero."]'::jsonb, 0, 'The solver refuses to report a negative internal rate of return, so one zero means the question was ill posed and the other means the answer is negative, and they print the same.'),
  ('fiscal', 'advanced', 'module', 'm05-numbers-to-distrust', 13, 'The resource rent tax base is the contractor profit share minus `totalCapex` times `rrtUpliftPct` divided by 100. What does the default of 20 grant over the project life?', '["A fifth of the capex, deducted once in year 1 alongside the capital spend it uplifts.", "A fifth of the capex in each year until the capital has been recovered, after which the deduction stops.", "Five times the whole capex, because the subtraction is made in every one of the 25 years.", "A fifth of the profit share each year, which is what makes the relief proportional to the rent the tax is aimed at."]'::jsonb, 2, 'Total capex on the default project is 500.0000 million USD and the engine calls the annual treatment a screening approximation in its own comment.'),
  ('fiscal', 'advanced', 'module', 'm05-numbers-to-distrust', 14, 'Sweeping `rrtUpliftPct` on the Brazil - Concession instruments with the corporate income tax set to zero, so the resource rent tax stands alone, the total tax reads 62.5794 at an uplift of 20, 1.0282 at 30 and 0.0000 at 50. What does the last row show?', '["The resource rent tax reaching its own minimum tax floor, below which the stack will not charge a regime whose base has gone negative.", "The instrument switched off by a parameter that never mentions switching anything off, with no first year carrying a positive charge.", "The regime''s whole tax bill going to zero, since the isolated sweep is the published Brazil stack with its corporate income tax of 34 percent inside it.", "A rounding of a small positive charge, since the sweep prints tax to four decimals and the charge in the later years is smaller than that."]'::jsonb, 1, 'Ten points of uplift, from 20 to 30, take the total from 62.5794 to 1.0282, and at 50 the first year with a positive charge is null.'),
  ('fiscal', 'advanced', 'module', 'm05-numbers-to-distrust', 15, '`rrt_uplift_default_20` omits the uplift field and returns total tax of 1638.5664 million USD, while `rrt_uplift_zero_respected` sets it to 0 and returns 2607.5549. What does a blank field give?', '["A zero uplift, on the ordinary rule that an absent numeric field contributes nothing to the base it would have reduced.", "Whatever the template carried, since a comparison fills a missing tax field from the regime it was cloned from before the ledger runs.", "An error the comparison reports rather than a ledger, because the resource rent tax cannot be charged without a stated uplift.", "The default of 20, and 1638.5664 million USD with it."]'::jsonb, 3, 'Contractor net cash flow moves with it, 1812.4483 million USD on the default against 843.4598 on an explicit zero, so omitting the field is a decision.'),
  ('fiscal', 'advanced', 'module', 'm06-the-expert-reading', 1, 'In what order is a graded fiscal comparison worked?', '["Verdicts first, because they name the regimes worth examining and save reading five columns that only restate them.", "Project, then instruments, then the summary and its sort, then each sweep at the range it actually ran, and the verdicts last.", "Summary first, since the sort settles which regime is best for the contractor, and the project inputs behind it cannot change a ranking.", "Sweeps first, because they are the only outputs that re-run the whole ledger and everything else is a total taken from them."]'::jsonb, 1, 'Most wrong answers start at the verdicts, and a verdict is the one output that has already rounded, ranked and dropped the range it ranked over.'),
  ('fiscal', 'advanced', 'module', 'm06-the-expert-reading', 2, 'Which set of inputs is the teaching field ODIDI?', '["Oil 10000 bbl/d, gas 50 Mscf/d and NGL 1500 bbl/d on a deck of 70, 3.5 and 30, with total capex of 500.0000 million USD and a discount rate of 10 percent.", "Oil 30000 bbl/d declining 12 percent with no gas and no NGL, which is the field every published comparison case is run on.", "Oil 8000 bbl/d with a 25 year horizon set by the decline, capex spread across the first three years and a discount rate the comparison chooses.", "Oil 8000 bbl/d declining 14 percent a year, gas 40 Mscf/d declining 9 percent, NGL 900 bbl/d declining 15 percent, capex of 260, 120 and 40 million USD, fixed opex 12 million USD a year with variable opex 4 USD per boe, and a discount rate of 12 percent."]'::jsonb, 3, 'Its deck reads oil 45, gas 3 and NGL 25 in year 1, steps at year 6 to 65, 3.8 and 32, and steps again at year 12 to 85, 4.2 and 38.'),
  ('fiscal', 'advanced', 'module', 'm06-the-expert-reading', 3, 'Every one of the six templates returns a total revenue of 1236.1983 million USD on ODIDI. Why?', '["A regime touches neither production nor price, so gross revenue is a property of the field and the deck alone and every difference below it is the regime.", "Because the comparison computes revenue once and copies it into each summary row, which is why a per regime revenue column is not returned.", "Because all six templates happen to recover cost to a similar limit, and revenue is reported after cost recovery rather than before it.", "Because the sweep re-runs each regime from the same scaled deck, so any revenue difference between them cancels over the 25 years."]'::jsonb, 0, 'On the default project the shared figure is 2686.9277 million USD and on the test project 7001.1938, and contractor net cash flow underneath still moves by hundreds of millions.'),
  ('fiscal', 'advanced', 'module', 'm06-the-expert-reading', 4, 'The ODIDI summary is headed by Brazil - Concession at -5.8662 million USD. What does rank 1 mean there?', '["Best on the sort''s two keys, contractor NPV first and payback year second, which is what puts a year 6 regime at the head of the table.", "Break even, since a value that small sits inside the precision the summary reports.", "Least bad, since all six ODIDI NPVs at 12 percent are negative, down to -58.1813 million USD.", "Best for the contractor and best for the government at once, because on ODIDI the take column runs opposite to the NPV column."]'::jsonb, 2, 'The verdict names it best for the contractor at -5.9 million USD, and the sentence is correct while the project is still a loss.'),
  ('fiscal', 'advanced', 'module', 'm06-the-expert-reading', 5, 'On ODIDI which regime collects the most for the government, and where does it sit in the summary?', '["Angola - Deepwater PSC, 316.7898 million USD, at rank 6.", "Nigeria - PIA (2021), 312.9610 million USD, at rank 5, the highest take on the field and the reason it ranks below the concessions.", "Generic Royalty/Tax, 242.1194 million USD, at rank 2, which is the row the sort puts next to the contractor''s own best.", "Brazil - Concession, 232.9950 million USD, at rank 1, since the regime that leaves the contractor most also runs the largest revenue base."]'::jsonb, 0, 'The summary is sorted by contractor NPV descending and by nothing else, so the take column has to be read from the take column.'),
  ('fiscal', 'advanced', 'module', 'm06-the-expert-reading', 6, 'On ODIDI, Ghana - Deepwater reads an effective tax rate of 36.5071 at rank 3 and USA - Gulf of Mexico reads 32.8219 at rank 4. What does that show?', '["That the two rows were computed at different discount rates, since the summary discounts each regime at the rate its template carries.", "That the effective tax rate does not follow the sort either.", "That the effective tax rate column is the sweep''s version on those two rows, which is the definition that has no capex added back.", "That the sort has a secondary key on the effective tax rate ascending, which only shows itself when two NPVs are close together."]'::jsonb, 1, 'The rate is take over take plus contractor take with capex added back, both totals undiscounted, while the sort key is discounted at 12 percent.'),
  ('fiscal', 'advanced', 'module', 'm06-the-expert-reading', 7, 'A regime in this sandbox is four fields. Which are they?', '["The royalty, the discount rate, the profit split and the tax block, since the rate is what turns a regime''s timing into a value.", "The royalty, the cost recovery limit, the capex schedule and the tax block, because when capital is spent decides what is recovered.", "The royalty, flat or sliding on the oil price; the cost recovery limit as a percent of revenue after royalty; the profit split, flat or tiered on the R factor; and the tax block.", "The royalty, the cost recovery limit, the profit split and the production forecast, which is what makes one regime harsher than another."]'::jsonb, 2, 'The tax block holds corporate income tax, the resource rent tax, a minimum tax and an `rrtUpliftPct` that defaults to 20 when the field is absent.'),
  ('fiscal', 'advanced', 'module', 'm06-the-expert-reading', 8, 'A capstone answer states the uplift as absent rather than stating a number. Why does that matter?', '["It does not matter, because the resource rent tax is charged on the profit share and the uplift only moves the year the charge begins.", "Because the comparison rejects a regime with an absent field and substitutes the template it was cloned from, which changes more instruments than the uplift alone.", "Because an absent field is reported as null in the summary, and a null in any instrument suppresses the whole tax block for that regime.", "A missing uplift is not a zero uplift: the published pair returns total tax of 1638.5664 million USD on the default and 2607.5549 on an explicit zero."]'::jsonb, 3, 'Contractor net cash flow moves with it too, 1812.4483 million USD against 843.4598, so the blank field is a decision and has to be written down as one.'),
  ('fiscal', 'advanced', 'module', 'm06-the-expert-reading', 9, 'How should each sweep be quoted in a written answer?', '["Both as the ranges their axes carry, 40 to 120 USD per bbl and 0.8 to 1.5, since those are the ranges a reader of the chart will check against.", "The price sweep as nine points moving all three stream prices together and the capex sweep as eight points, the last of which the golden publishes on its own.", "Whichever range the verdict sentence names, because the verdict is computed from the series and therefore carries the range with it.", "The price sweep as nine oil prices from 40 to 120 USD per bbl with gas and NGL unmoved, and the capex sweep as seven points ending at a multiplier of 1.4."]'::jsonb, 3, 'ODIDI''s capex losses of 150.9021 million USD for Ghana - Deepwater and 215.1075 for Angola - Deepwater PSC are losses to a 40 percent overrun, not to the 50 percent the axis promises.'),
  ('fiscal', 'advanced', 'module', 'm06-the-expert-reading', 10, 'What has to be checked under every government share before it is quoted?', '["Total government take and total contractor net cash flow for that regime.", "The swept price the point belongs to, since a share read off the wrong one of the nine labels is the common error on this chart.", "The summary''s effective tax rate for the same regime, which is the same ratio with the capex add-back and can be used to correct the point.", "The number of regimes in the comparison, because the share is normalised across the regimes plotted and moves when one is added or removed."]'::jsonb, 0, 'If the contractor total is negative the number is not a share, and if the two do not sum above zero the curve reads 0.0000 and means nothing at all.'),
  ('fiscal', 'advanced', 'module', 'm06-the-expert-reading', 11, 'What does this comparison refuse to be?', '["A screening tool, since it models every instrument a real contract carries and is therefore built for a final investment decision rather than a comparison.", "A fiscal truth, a production forecast and a capex schedule: it generates production over a fixed 25 years, spends every dollar of capex in year 1, and hands Nigerian fiscal math to the Petroleum Economics Studio engine.", "A regime comparison, because its templates are illustrative and only the two Designer defaults are pinned by published cases.", "A discounted measure, since every column it returns is an undiscounted lifetime total and the NPV is supplied by the caller."]'::jsonb, 1, 'It also models no abandonment, no depreciation, no loss carryforward against tax, no ring fence and no valuation date, and a year is its own discount exponent.'),
  ('fiscal', 'advanced', 'module', 'm06-the-expert-reading', 12, 'Under the PIA template on ODIDI, cumulative contractor net cash flow first turns positive in year 7 at 6.1264 million USD, against capex of 420.0000. What does the payback year say?', '["That the contractor had recovered the whole 420.0000 million USD of capex, and 6.1264 million USD of profit on top of it, by the end of year 7 discounted at 12 percent.", "That the project is viable, since a payback inside the first third of a 25 year life is what the summary''s payback column is there to show.", "Only that the cumulative crossed zero in that year, on a field where the cumulative later peaks at 138.3627 and falls back to 113.0236 million USD by year 25.", "That year 7 is the best year of the ledger, because it is the year the contractor''s own cash position stopped falling and began to rise."]'::jsonb, 2, 'Payback is undiscounted and is a first crossing rather than a maximum, and the same ledger returns an NPV of -43.7842 million USD at 12 percent.'),
  ('fiscal', 'advanced', 'module', 'm06-the-expert-reading', 13, 'ODIDI returns contractor net cash flow of 113.0236 million USD under the PIA template and 148.3166 under USA - Gulf of Mexico, on one revenue of 1236.1983. Where did the difference go?', '["To the government, whose take is 312.9610 against 277.6679 million USD on the same two runs.", "To cost recovery, which is 779.6254 under the PIA template against 785.9313 and is the larger of the two differences between the runs.", "To opex and capex, which the PIA template charges against the contractor''s line while a concession charges them against profit oil.", "To the discount rate, since the two regimes return different NPVs at 12 percent."]'::jsonb, 0, 'Opex plus capex is the same 810.2137 million USD in both ledgers, so nothing but the four instruments separates the two contractor totals.'),
  ('fiscal', 'advanced', 'module', 'm06-the-expert-reading', 14, 'Under the PIA template the ODIDI royalty runs 5.7145 million USD in year 5 and 9.3986 in year 6, on gross revenue of 76.1939 and 93.9859. What moved?', '["The R factor passed 1.0 in year 6, and the royalty rate in this template is keyed to the R factor tranche the year selects.", "Cost recovery closed the pool in year 6, and royalty is charged on revenue after cost recovery once the pool has cleared.", "Production rose in year 6, lifting revenue and royalty together.", "The deck stepped at year 6 and carried the oil price over a sliding royalty threshold."]'::jsonb, 3, 'The royalty tier changing inside a project''s life is the one thing none of the published template cases do, and it is why the ODIDI royalty column moves for two reasons.'),
  ('fiscal', 'advanced', 'module', 'm06-the-expert-reading', 15, 'Nigeria - PIA (2021) has a capex resilience of 97.7613 million USD and also of 118.3685. Which is right?', '["The first, because the second figure came from calling the ledger function directly at a multiplier the comparison never sweeps and never returns to a reader.", "Both, each for its own question: 97.7613 is the loss over the seven points the sweep visited and 118.3685 the loss over the eight the axis advertised.", "The second, because the axis label is the published range, and a resilience figure quoted short of that range understates the exposure the chart set out to price.", "Neither, because a loss between two endpoints is not a resilience figure at all when the curve between them is not a straight line."]'::jsonb, 1, 'A number without its definition is not a number, which is the same lesson as one regime reading 59.6432 and 76.7282 as its effective tax rate.'),
  ('fiscal', 'advanced', 'final', null, 1, 'One call to `runFiscalComparison` returns four objects. Which are they, and which one is ordered?', '["`summary`, `annualCashFlows`, `sensitivityData` and `insights`, and only the summary is ordered, by contractor NPV descending.", "`summary`, `annualCashFlows`, `sensitivityData` and `insights`, all four ordered by the same contractor NPV so their rows line up.", "A summary and three charts, with the ledgers rebuilt on demand from the summary row a reader clicks.", "One ledger per regime and a set of verdicts, from which the summary table is assembled by the panel that renders it rather than by the engine."]'::jsonb, 0, 'Every ledger inside `annualCashFlows` is 25 rows long because the horizon is fixed, and nothing but the summary carries an order.'),
  ('fiscal', 'advanced', 'final', null, 2, 'On the Suite test project the comparison of Flat against Complex returns Flat at an NPV of 1262.3470 million USD, which is the row Generic Royalty/Tax returns on the same project. What does that show?', '["That the comparison caches a ledger by project and reuses it whenever two regimes return the same government take.", "That the test project is insensitive to fiscal terms, since Complex returns 709.3642 million USD on the same run.", "A name is not a regime: the two carry identical instruments, so they return an identical row.", "That Generic Royalty/Tax is the fallback the engine substitutes whenever a regime is passed without a full set of four instruments."]'::jsonb, 2, 'Complex on the same project returns 709.3642 million USD of NPV and 2934.0177 of government take, so the field is not the reason the two agree.'),
  ('fiscal', 'advanced', 'final', null, 3, 'USA - Gulf of Mexico on the default project runs cumulative contractor net cash flow of -310.0117, then -140.2337, then 8.9905 million USD, and an R factor of 0.512217, then 0.922481, then 1.254640. What are its payback and payout years?', '["Payback year 4 and payout year 3, because the cumulative has to clear the capex rather than merely turn positive.", "Both year 3, read from two different columns: cumulative contractor cash for one and the R factor for the other.", "Both year 3, and they agree because payout is the discounted form of the same crossing.", "Payback year 3 and payout year 2, since the R factor is above 1.0 as soon as cumulative revenue exceeds the first year''s opex."]'::jsonb, 1, 'Payback is the first year cumulative contractor net cash flow is above zero and payout the first year the R factor is above 1.0, so one is after tax cash and the other a gross ratio.'),
  ('fiscal', 'advanced', 'final', null, 4, 'Two regimes in one comparison return exactly the same contractor NPV. Where do they sit in the summary?', '["Ordered by government take ascending, which is the tie break the comparison applies before it hands the rows back to the caller.", "Ordered by payback year and then by the R factor payout year, the two integer columns the summary already carries for every regime.", "Either of them may head the table, since a tie inside a floating point sort goes to whichever rounding error happened to be the smaller.", "In the order they were passed in, because the sort has no secondary key."]'::jsonb, 3, 'The comparison exposes no option to sort on anything else, so `summary[0]` guarantees the highest contractor NPV at the comparison''s discount rate and nothing more.'),
  ('fiscal', 'advanced', 'final', null, 5, 'The summary''s effective tax rate is charged with a great deal that no tax authority calls tax. What is in the numerator?', '["Government take, which is royalty plus the government''s share of profit oil plus tax, so USA - Gulf of Mexico reads 34.0485 percent while its only tax is corporate income tax at 21 percent.", "Tax alone, which is why Angola - Deepwater PSC reads 53.4534 percent against instruments carrying 25 and 50 percent.", "Tax plus royalty, with the profit oil split excluded because it is a share of production rather than a charge on income.", "Government take net of the cost the state recovered, which is what turns the ratio into a rate on profit rather than on cash."]'::jsonb, 0, 'A flat royalty of 18.75 percent contributes 503.7989 million USD of the 764.5528 that regime collects.'),
  ('fiscal', 'advanced', 'final', null, 6, 'What does `summary[0]` guarantee on any comparison?', '["The highest contractor NPV and the fastest payback, since the two move together on every published comparison in the course.", "The best result for the contractor on NPV, IRR and payback, which is what makes it the row a recommendation is written from.", "The highest contractor NPV at the comparison''s discount rate, and nothing else.", "The lowest government take, because take and contractor NPV are the two sides of one revenue total and must run opposite each other."]'::jsonb, 2, 'On the default project rank 2 returns an IRR of 40.2125 percent and rank 3 returns 43.0919, so even the IRR column is already out of order.'),
  ('fiscal', 'advanced', 'final', null, 7, 'A reader takes a government share at 75 USD per bbl off the price chart. What have they read?', '["An interpolation the engine supplies between neighbouring swept points, which is why the sweep returns a curve rather than nine values.", "The chart''s own line between two computed points, because the sweep has nine fixed prices and nothing between them.", "A tenth point, because the sweep adds any price the project''s own deck carries to its nine fixed prices before it runs.", "A share at the deck''s own price, reproduced exactly."]'::jsonb, 1, 'The nine prices are fixed and no input changes them, so a project whose economics turn at 45 USD per bbl cannot be examined there at all.'),
  ('fiscal', 'advanced', 'final', null, 8, 'At `price_40_pia_default` the run returns an NPV of -51.1673 million USD, payback in year 9 and 5.9578 million USD still unrecovered at the end of 25 years. What does the unrecovered pool show?', '["That the sweep charges the whole capex again at each point, so a low price cannot clear a pool that keeps being refilled.", "That the pool is written off in the final year, which is why the closing figure is small rather than the whole unrecovered cost.", "That the project stopped producing before year 25, leaving cost in the pool that later production would have recovered.", "A cost recovery limit that never binds at the deck price binds hard at the bottom of the sweep."]'::jsonb, 3, 'At 50 USD per bbl the pool closes to 0.7642 million USD and from 60 upward it closes completely.'),
  ('fiscal', 'advanced', 'final', null, 9, 'USA - Gulf of Mexico shows a price climb of -17.2498 percentage points and Generic Royalty/Tax -10.1897 on the default project. What makes those two regressive?', '["A fixed royalty rate and a fixed tax rate on a growing profit hand the government a shrinking fraction once cost recovery has been paid off.", "A cost recovery limit that rises with price, which returns more of the contractor''s cost before any split is taken.", "A profit split tiered on the R factor, which walks the contractor into a more generous tranche as revenue grows.", "A minimum tax that binds at low prices and stops binding once the computed charge exceeds it."]'::jsonb, 0, 'The three templates whose split is tiered on the R factor climb instead, by 12.1305, 10.1420 and 7.8960 percentage points.'),
  ('fiscal', 'advanced', 'final', null, 10, 'Brazil - Concession returns a price climb of 6.0391 percentage points while its share falls from 50.0329 at 40 USD per bbl to 46.6052 at 60. How can both be true?', '["The climb is measured on the summary''s effective tax rate rather than the sweep''s, and the two definitions move in opposite directions.", "The share below 60 USD per bbl was produced by the guard rather than by a division, so those points are not on the curve at all.", "The climb is the last swept share minus the first, so it sees two points and hides the minimum between them.", "The climb averages the eight intervals between the nine points, which a single early fall cannot outweigh."]'::jsonb, 2, 'Ghana - Deepwater reverses twice inside a positive climb, from 76.7284 down to 76.4647 and from 77.2412 down to 77.0702.'),
  ('fiscal', 'advanced', 'final', null, 11, 'The published `price_below_every_threshold` case runs the default deck at a price multiplier of 0.5 and returns total gross revenue of 1419.0195 million USD against the deck''s own 2686.9277. Why is that more than half?', '["Because the sliding royalty fell below every tier, and revenue is reported after royalty in this ledger.", "The multiplier scales oil only, and the gas and NGL prices in the deck never move.", "Because the deck steps up at year 5 and year 10, and the multiplier is applied only to the first deck point.", "Because production rises to defend revenue when price falls, which is what the closed form decline does at the bottom of a deck."]'::jsonb, 1, 'The default project carries gas at 50 Mscf/d and NGL at 1500 bbl/d beside its oil, so a gas weighted project moves less across the sweep than the axis suggests.'),
  ('fiscal', 'advanced', 'final', null, 12, 'At every swept price the comparison recomputes an NPV, a payback year and an unrecovered pool for every regime. What becomes of them?', '["They are returned inside `sensitivityData` beside the share, which is how a panel draws a second series when a reader asks for one.", "They replace the summary row at whichever price the reader has selected, which is why the table moves when the chart is clicked.", "They are averaged across the nine points and reported as the regime''s sensitivity, which is the quantity the progressivity verdict ranks.", "They are discarded, because the chart plots one government share per regime per point."]'::jsonb, 3, 'Neither chart can tell a reader that a point it plotted came from a project that never paid back, so the totals underneath a point have to be fetched from the ledger.'),
  ('fiscal', 'advanced', 'final', null, 13, 'A real cost overrun raises capital and operating cost together and can push spending into later years. What does the capex sweep model?', '["One scalar on the whole capital programme, with drilling, facilities and subsea moving together, all of it still landing in year 1 and opex untouched.", "The capital and the operating cost together, in the fixed proportion the project''s own cost stack carries between them.", "The capital cost with its spending rescheduled across the first years, which is what separates an overrun from a larger project.", "The capital cost and the discount rate together, since an overrun that arrives later is worth less than one arriving in year 1."]'::jsonb, 0, 'It also holds price fixed at the deck at every multiplier, so nothing in the sweep answers what an overrun costs at a low price.'),
  ('fiscal', 'advanced', 'final', null, 14, 'The resilience verdict names USA - Gulf of Mexico the least resilient on the default project at 228.7953 million USD given up. What is the catch in that ranking?', '["The quantity is a percentage of base NPV, so a regime with a small base is penalised for a loss that is small in money.", "The quantity is an absolute amount, so a regime with more NPV to lose is penalised for having it, and that regime''s base NPV is 382.0660 million USD.", "The quantity is measured from the peak of the curve, so a regime that rises before it falls is charged for the rise as well.", "The quantity is discounted at 10 percent while the base NPV is not, so the two cannot be compared as amounts at all."]'::jsonb, 1, 'Angola - Deepwater PSC is named the most resilient at 84.8591 million USD given up, on a base NPV of 223.7100.'),
  ('fiscal', 'advanced', 'final', null, 15, 'Why can the price chart and the capex chart not be read as a matched pair?', '["One is computed from the summary and the other from the ledgers, so the two are drawn from different objects inside the returned result.", "One re-runs the whole comparison at each point while the other rescales the base case, so only one of the two is a set of full computations.", "One is a rate on the state''s side of the ledger at nine prices and the other is money on the contractor''s side at seven multipliers.", "One has nine points and the other has seven."]'::jsonb, 2, 'Only the capex chart''s values can be added or subtracted as amounts, and only the price chart''s values can be compared between projects of different sizes.'),
  ('fiscal', 'advanced', 'final', null, 16, 'Why can a capex loss of 84.8591 million USD on the default project not be carried to another field?', '["Because the losses are quoted in million USD and two fields of different size need the figure expressed as a percentage first.", "Because a second field would be swept over a different capex range, since the multipliers are taken from the project''s own capex lines.", "Because the verdict rounds to one decimal place, and a figure carried between fields loses the digits that separated the regimes.", "The ordering itself changes: on ODIDI the same six templates give up between 150.9021 and 215.1075 million USD."]'::jsonb, 3, 'Angola - Deepwater PSC gives up the least of the six on the default project and the most of the six on ODIDI, so a resilience ranking belongs to a field.'),
  ('fiscal', 'advanced', 'final', null, 17, 'Which case does neither sweep cover?', '["An overrun arriving at a low price, because the price sweep holds capex at the base case and the capex sweep holds price at the deck.", "A price above 120 USD per bbl, which the price sweep stops at and the capex sweep cannot reach by raising capital cost.", "A regime with no resource rent tax, since both sweeps assume a tax stack whose base moves with the capex they vary.", "A project whose capex is spent later than year 1, which is the only assumption the two sweeps make differently from each other."]'::jsonb, 0, 'The Angola template on the default project at three times capex reads a government share of 0.0000 at 40 USD per bbl and 2223.0766 at 50, and neither chart as drawn would have suggested it.'),
  ('fiscal', 'advanced', 'final', null, 18, 'A resilience verdict names a different regime on a second run. Which three explanations must be separated?', '["The discount rate moved, the regime list moved, or the sweep was run before the summary had been sorted by contractor NPV.", "The field moved, the range moved, or there was nothing to rank in the first place.", "The capex lines moved, the deck moved, or the verdict was read from the price sweep rather than from the capex sweep.", "The tie break changed, the rounding changed, or the golden pinned a winner the engine no longer returns."]'::jsonb, 1, 'On the comparison built with capex of 20000 all six regimes give up 10909.090909 million USD, so the third explanation is not hypothetical.'),
  ('fiscal', 'advanced', 'final', null, 19, 'Which four claims did the Insights tab state that nothing had computed?', '["That the top NPV regime also collected the least for the government, that payback and payout coincide, and two rankings taken from the sweeps.", "That the summary was sorted on four keys at once, so a reader could take any column''s order off the table without reading the column.", "That the top NPV regime also paid back fastest, that the second ranked regime maximised government revenue, and a capex resilience ranking and a price response ranking.", "That every regime pays back, that every IRR is a root, that the effective tax rate is a tax rate, and that the axis labels match the sweeps."]'::jsonb, 2, 'All four now come from the numbers, and a claim that cannot be supported is omitted rather than guessed.'),
  ('fiscal', 'advanced', 'final', null, 20, '`insights_flipped` ranks Beta first by NPV at 300.0 million USD, and the government verdict still names Beta. What is the case pinning?', '["That the government verdict reads the take column rather than the sort, so its answer does not change when the NPV order does.", "That the two verdicts are computed from one reduce, so whichever regime heads the summary is named by both of them.", "That a flipped NPV order flips the government verdict with it, which is the coupling `deriveInsights` was written to keep.", "That the government verdict falls back on the first summary row whenever two regimes collect within one decimal place of each other."]'::jsonb, 0, 'Beta collects 900.0 million USD against 400.0 for Alpha in both cases, and the sentence is the same in both.'),
  ('fiscal', 'advanced', 'final', null, 21, 'On `insights_ties` the government verdict reads that Alpha collects the most, 900.0 million USD against 900.0 million USD for Beta. What produced that sentence?', '["A rounding to one decimal place applied before the ranking, which is what turns two different totals into one printed figure.", "A tie break on the summary order, which the engine applies deliberately so that a verdict always names exactly one regime.", "An alphabetical tie break, which is why the regime named first in the sentence is also the one earlier in the alphabet.", "A strict comparison inside a reduce, which keeps the first of two equal values."]'::jsonb, 3, 'The ranking runs at full precision and only the sentence rounds, so a tie in the sentence is not always a tie in the quantity, and here it is.'),
  ('fiscal', 'advanced', 'final', null, 22, 'What does `deriveInsights` do with a claim it cannot support?', '["It returns the verdict with the regime name left empty, so a panel can render the heading and leave the sentence blank.", "It omits the verdict, which is why a single regime returns three and an empty comparison returns none.", "It returns the verdict with the quantity set to zero, which is the same convention the share curve uses when its guard fires.", "It returns a verdict stating that the claim could not be supported, so that a reader is told which ranking was attempted."]'::jsonb, 1, 'Both sweeps still run on a single regime comparison and still produce a series, and the function declines to name a winner among one.'),
  ('fiscal', 'advanced', 'final', null, 23, 'On the ODIDI comparison the capex verdict names Ghana - Deepwater and the price verdict names Ghana - Deepwater. Is that agreement a finding?', '["No, because both verdicts are produced by the same reduce over the same series and must always name the same regime.", "No, because a climb of 1.9971 percentage points is inside the precision the verdict prints, so the price verdict ranked nothing.", "It is a real agreement on that field, since Ghana gives up the least at 150.9021 million USD and climbs the most at 1.9971 percentage points.", "Yes, and it carries to any field, because a regime that takes a share of the upside absorbs a share of the downside."]'::jsonb, 2, 'On the default project the pairing is looser, with Angola - Deepwater PSC first by climb at 12.1305 and Ghana - Deepwater second by loss at 88.2631.'),
  ('fiscal', 'advanced', 'final', null, 24, 'The contractor verdict on ODIDI prints -5.9 million USD and an IRR of 11.4 percent. What did it rank?', '["The first row of the summary at full precision, -5.8662 million USD and 11.4055 percent, because the sort has already put the highest contractor NPV there.", "The largest contractor NPV it could find across the six ledgers, recomputed at the comparison''s discount rate before the sentence was built.", "The rounded figures themselves, which is why two regimes printing the same value are reported as a tie by this verdict.", "The undiscounted lifetime contractor net cash flow, which on ODIDI is 192.9896 million USD for that regime."]'::jsonb, 0, 'Every insight sentence rounds money and rates to one decimal place while the ranking underneath runs at full precision.'),
  ('fiscal', 'advanced', 'final', null, 25, '`calculateIRR` returns 102400.0000 percent on flows of -1 then 2000, where the true rate is 199900 percent. What did the solver do?', '["It bisected to the tolerance it was given, which on a curve this flat is reached long before the root.", "It returned a clamp written into the function to stop an unbounded search from reporting an infinite rate.", "It found a second root, since flows that change sign once can still admit two rates and the function returns the smaller.", "It stopped at the top of its own bracket, 100 percent doubled ten times, with the NPV there still positive at 0.0009."]'::jsonb, 3, 'The NPV at 199900 percent is 0.0000 and at 400000 percent is -0.0001, so the root is real and the reported value is a bound.'),
  ('fiscal', 'advanced', 'final', null, 26, 'Two published cases return an IRR of 0.0000 percent, one with an NPV at 10 percent of 25.6198 million USD and one of -16.5289. What separates them?', '["One was stopped by the bracket and the other by the tolerance, so one zero is a bound and the other a converged root.", "One has flows that never change sign on a profitable project and the other loses money at every rate, and the solver refuses to report a negative rate.", "One is a project that breaks even exactly and the other a project whose root the bisection could not locate inside 80 steps.", "Nothing separates them: both are ill posed, and the profitable one only looks different because its NPV is quoted at a rate the case did not use."]'::jsonb, 1, 'A reader who rejects 102400 percent as absurd and accepts 0.0000 percent as break even has caught the harmless case and swallowed the dangerous one.'),
  ('fiscal', 'advanced', 'final', null, 27, 'What does an `rrtUpliftPct` of 20 do to the resource rent tax base?', '["It uplifts the capex by a fifth before it is recovered, so the pool clears later and the base appears later.", "It subtracts a fifth of total capex from the profit share in the first year only, as a capital allowance on the year the money was spent.", "It subtracts a fifth of total capex from the profit share in every one of the 25 years, so the relief over the life is five times the capex.", "It raises the resource rent tax rate by a fifth in the years the project is still recovering its capital."]'::jsonb, 2, 'Total capex on the default project is 500.0000 million USD, and the engine calls the annual treatment a screening approximation in its own comment.'),
  ('fiscal', 'advanced', 'final', null, 28, 'In the isolated uplift sweep, where the corporate income tax is set to zero so the resource rent tax stands alone, an uplift of 50 returns total tax of 0.0000 and a first year with a positive charge of null. What has happened?', '["The instrument has been switched off by a parameter whose name says nothing about switching anything off.", "The tax has been deferred past the 25 year horizon and falls in later years.", "The base has gone negative and the minimum tax has taken over, which is why the charge is reported as zero rather than as a credit.", "The sweep has left the range the engine supports, since an uplift above the tax rate of 40 percent is not a defined input."]'::jsonb, 0, 'Ten points of uplift, from 20 to 30, already take the total from 62.5794 to 1.0282 million USD.'),
  ('fiscal', 'advanced', 'final', null, 29, 'Why does the capex sweep return seven points rather than eight?', '["The engine drops the last point to keep the axis readable.", "The loop counts steps from 0.8 in tenths and seven steps is what the range of 0.7 in the published cases allows.", "The last multiplier is reserved for the direct call the golden publishes beside the sweep, so it is computed but not returned.", "The accumulating multiplier reaches 1.5000000000000004 and fails its own test."]'::jsonb, 3, 'The engine returns the labels 0.8, 0.9, 1.0, 1.1, 1.2, 1.3 and 1.4, and the axis it is drawn against still promises 1.5.'),
  ('fiscal', 'advanced', 'final', null, 30, 'The verdict quotes Angola - Deepwater PSC as giving up 84.8591 million USD across the swept capex range. What is understated, and by how much?', '["The base NPV, which is 223.7100 million USD at the base multiplier and is the figure the sentence should have quoted.", "The range, and with it the loss: over the eight points the axis advertises the same regime gives up 107.3918 million USD.", "The winner, since Angola gives up the least over seven points and USA - Gulf of Mexico gives up the least over eight.", "Nothing is understated, because the sweep reports the range it ran and the axis label has no bearing on the number."]'::jsonb, 1, 'Every resilience number on that chart is understated in the same way, USA - Gulf of Mexico at 228.7953 against 267.7301 million USD.'),
  ('fiscal', 'advanced', 'final', null, 31, 'Every rate in a written answer on ODIDI is correct and the resilience answer is still wrong. What was skipped?', '["The instruments, since a resilience figure depends on the resource rent tax uplift and the uplift is the field readers omit.", "The sort, since a resilience verdict is read off the summary''s first row.", "The ranges: the capex sweep stops at a multiplier of 1.4 while the chart promises 1.5.", "The discount rate, since ODIDI is discounted at 12 percent and the swept losses are reported at the comparison''s own 10."]'::jsonb, 2, 'Ranges and definitions are where the marks are lost, not rates, and ODIDI''s losses of 150.9021 and 215.1075 million USD price a 40 percent overrun.'),
  ('fiscal', 'advanced', 'final', null, 32, 'What does this model hand to someone else?', '["Nigerian fiscal truth, which belongs to the Petroleum Economics Studio engine, and any regime whose real burden lives in an instrument the four fields cannot express.", "The comparison of regimes against each other, which needs a full contract model carrying depreciation, ring fencing and loss carryforward rather than four instruments on one ledger.", "The generation of a production profile, which it refuses to attempt and takes instead from whatever forecast the caller supplies alongside the project, its deck and its cost stack.", "The discounting, which is left to the caller because the engine returns undiscounted lifetime totals only."]'::jsonb, 0, 'The answer is not to bend a rate until the total looks right, and the sandbox also models no abandonment, no depreciation, no loss carryforward, no ring fence and no valuation date.'),
  ('fiscal', 'advanced', 'final', null, 33, 'On ODIDI the highest contractor NPV and the largest government take sit in different rows. Which rows, and why is that not a contradiction?', '["Brazil - Concession heads both, and the appearance of a split comes from the effective tax rate column, which is a ratio rather than a total.", "Brazil - Concession at -5.8662 million USD heads the sort while Angola - Deepwater PSC collects 316.7898 at rank 6, because the sort key is discounted and the take column is an undiscounted lifetime total.", "Generic Royalty/Tax heads the sort at -13.3840 million USD while Nigeria - PIA (2021) collects 312.9610 million USD, and the two differ because one of those columns is a percent of revenue and the other is money over the whole life.", "Angola - Deepwater PSC heads both on ODIDI, which is what makes the field a poor one to rehearse a comparison on."]'::jsonb, 1, 'All six ODIDI NPVs at 12 percent are negative, so the head of the sort is the least bad rather than the good one.'),
  ('fiscal', 'advanced', 'final', null, 34, 'Under the PIA template on ODIDI the contractor net cash flow reads -1.0205 million USD in year 20 and stays negative to year 25, while the cumulative ends at 113.0236. What does that mean for the payback year?', '["Payback is recomputed at the end and reported as the last year the cumulative was above zero, which on this ledger is year 25.", "Payback is null on this ledger, because a cumulative that turns down inside the horizon has not recovered the capital.", "Payback is unaffected because the engine reads only the years before the R factor passes 1.0, which on ODIDI is year 6.", "Payback is a first crossing and not a high water mark, and the cumulative peaks at 138.3627 million USD before falling back."]'::jsonb, 3, 'The cumulative first turns positive in year 7 at 6.1264 million USD, and late year opex against a declining revenue is what pulls it back.'),
  ('fiscal', 'advanced', 'final', null, 35, 'On the Designer''s defaults the Concessionary regime reads 46.3452 percent in the summary and 59.6210 percent on the price chart at the base price. Which one is the rate on profit, and why do they differ?', '["The summary''s 46.3452, because it adds total capex back to the contractor side, while the chart''s 59.6210 divides the same two totals with nothing added back.", "The chart''s 59.6210, because the sweep re-runs the whole ledger at each of its nine prices and therefore works on profit, while the summary reports a single ratio taken on cash.", "The summary''s 46.3452, because it is discounted at 10 percent while the chart''s number is an undiscounted lifetime ratio.", "Neither, since both divide take by take plus contractor cash and the difference between them is the swept price."]'::jsonb, 0, 'The Nigerian PIA (PSC) regime shows the same pair, 55.5380 against 71.4471, a gap of 15.9091 percentage points on one screen.'),
  ('fiscal', 'advanced', 'final', null, 36, 'The payback column of `cmp_all_templates_default_project` reads 3, 3, 3, 4, 3 and 4 down the summary. What does the payback verdict then report?', '["The regime with the smallest government take, since the tie break falls through to the next column in the summary.", "No verdict at all, because a four way tie at the top cannot be ranked and an unsupportable claim is omitted.", "The regime with the highest NPV, because the tie is broken by summary order and the summary is sorted on contractor NPV.", "The regime whose R factor payout year is earliest, which is the tie break the engine applies whenever an integer column ties in the summary."]'::jsonb, 2, 'Four regimes pay back in year 3 and the sentence names Generic Royalty/Tax, which leads the sort at 397.0445 million USD, so the verdict is the NPV ranking wearing a different label.'),
  ('fiscal', 'advanced', 'final', null, 37, 'A progressivity verdict is returned on a comparison where every point of every share series is 0.0000. How is that possible?', '["The verdict falls back on the summary''s effective tax rate whenever the sweep returns no usable series, and that column carries no guard that can zero it.", "The verdict ranks the difference between two series points, and a series of zeros gives a difference of zero, which ranks like any other number.", "The verdict is computed before the guard is applied, so it ranks the shares the division would have produced without it.", "The verdict treats a zeroed series as missing and names the regime with the largest government take instead."]'::jsonb, 1, 'On `cmp_never_recovers` the guard fires at all nine prices for all six templates, and the sentence still calls Nigeria - PIA (2021) the most progressive on a climb of 0.0 percentage points.'),
  ('fiscal', 'advanced', 'final', null, 38, 'A reader quotes the resilience verdict for Angola - Deepwater PSC on the default project. Which two separate checks does that number need?', '["Whether the discount rate matches the project and whether the regime''s four instruments were taken from the template rather than the Designer.", "Whether the sweep re-ran every regime and whether the loss was measured from the peak of the curve rather than from its first point.", "Whether the capex lines were scaled together and whether the opex moved with them.", "Whether the ranked quantities are separated at all, and whether the swept range is the range the answer was about."]'::jsonb, 3, 'The pick comes from a strict less than in a reduce, and the quantity comes from seven points ending at a multiplier of 1.4 rather than the eight the axis promises.'),
  ('fiscal', 'advanced', 'final', null, 39, 'On the default project the price climb and the capex loss rank the six templates in nearly the same order. What connects the two sweeps?', '["A regime that takes a rising share of the upside absorbs a share of the downside, so the contractor''s NPV under it moves less when capital cost rises.", "Both sweeps are computed from the same series, since the capex sweep is the price sweep re-expressed in money rather than in percentage points of government share.", "Both sweeps hold the other variable at the base case, so the two rankings are the same ranking measured twice.", "Both are endpoint differences over seven points, so a regime that leads one must lead the other by construction."]'::jsonb, 0, 'The most progressive template gives up the least at 84.8591 million USD and the two regressive ones give up 208.0310 and 228.7953, and the orders still differ row for row.'),
  ('fiscal', 'advanced', 'final', null, 40, 'On `cmp_never_recovers` every IRR reads 0.0000 and every payback is null. What may a reader do with those two columns?', '["Sort on the IRR, since a rate of zero is a real comparison point and the six regimes are separated somewhere below the four printed decimals.", "Read the null as the last year of the horizon, since a project that never pays back has by definition a payback of year 25.", "Neither may be sorted on: the zero is the solver declining to report a negative rate and the null is a payback that never arrived.", "Use the payback column to break the tie in the IRR column, because the two are computed from the same cumulative series."]'::jsonb, 2, 'The sort that produced the table was on contractor NPV, and what it ranks is six ways of losing money, from -15354.6816 to -15900.1132 million USD.'),
  ('fiscal', 'advanced', 'final', null, 41, 'ODIDI carries oil, gas and NGL while the Suite test project produces 30000 bbl/d of oil with no gas and no NGL. What does that change about a price sweep on each?', '["On the test project the sweep is meaningless because a single stream cannot show progressivity at all, and on ODIDI it is the only one of the two readings a fiscal analyst should quote.", "On the test project the multiplier is the whole revenue multiplier, and on ODIDI it moves oil only while gas at 40 Mscf/d and NGL at 900 bbl/d stay where the deck left them.", "On both the multiplier scales all three stream prices, and the difference is only that two of ODIDI''s streams are small.", "On the test project the sweep must re-run the decline as well, since an oil only field has no gas revenue to hold the ledger up at a low price."]'::jsonb, 1, 'A flat curve on a gas weighted field means the sweep did not move most of the revenue, not that the terms are neutral to price.'),
  ('fiscal', 'advanced', 'final', null, 42, 'The eighth capex point is not unreachable: the engine returns 58.5739 million USD for Nigeria - PIA (2021) at a multiplier of 1.5. Why is it not on the chart?', '["The golden withholds it so the oracle''s eighth point cannot pass as the engine''s.", "The chart drops any point whose contractor NPV falls below the base case by more than half, which is what 58.5739 does against 154.8286.", "The point exists only for templates carrying a resource rent tax, since the direct call needs an uplift to compute a base at that capex.", "The sweep that draws the chart never asks for it, and no input to the comparison can make it."]'::jsonb, 3, 'Reaching it means calling the ledger function directly at that multiplier, and the sweep''s range, step and count are written into the loop.');
